### The Code

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// --- CUSTOM RANDOM NUMBER GENERATOR (LCG) ---
// Parameters based on the classic Minstd.c constants
static unsigned long seed = 12345; 
static const unsigned long a = 1103515245;
static const unsigned long c = 12345;
static const unsigned long m = 2147483647; // 2^31 - 1

int next_random() {
    seed = (a * seed + c) % m;
    return seed;
}

// Helper function to get a number between 1 and 6
int roll_die() {
    return (next_random() % 6) + 1;
}

int main() {
    // Seed our custom generator with current time
    srand((unsigned int)time(NULL)); 

    printf("Rolling 6 dice...\n\n");

    for (int i = 1; i <= 6; i++) {
        int result = roll_die();
        printf("Die %d: %d\n", i, result);
    }

