### Source Code (`dice_sim.c`)

```c
#include <stdio.h>

// --- Custom Random Number Generator (Linear Congruential Generator) ---

// Define constants for the LCG algorithm
// Formula: next = (a * current + c) % m
#define M 2147483647 // 2^31 - 1 (Prime modulus)
#define A 1103515245 // Multiplier
#define C 12345      // Increment
#define SEED 42      // Initial seed (can be changed)

// Current state of our random number generator
static unsigned long state = SEED;

// Function to get the next pseudo-random number
unsigned long my_rand(void) {
    state = (A * state + C) % M;
    return state;
}

// Wrapper function to return a number between min and max (inclusive)
int my_rand_range(int min, int max) {
    if (min > max) {
        int temp = min;
        min = max;
        max = temp;
    }
    // Convert the large random integer to a range [min, max]
    return min + (my_rand() % (max - min + 1));
}

// --- Main Program Logic ---

int main() {
    int num_dice = 6;
    int die_values[6];
    int total_sum = 0;

    printf("--- Simulating %d Dice Rolls ---\n\n", num_dice);

    // Loop to roll each die
