        // Generate a random number between 1 and 6
        int roll = my_rand_range(1, 6);
        die_values[i] = roll;
        total_sum += roll;

        printf("Die %d: %d\n", i + 1, roll);
    }

    // Print summary
    printf("\n------------------\n");
    printf("Total Sum: %d\n", total_sum);

